// Get the current company name from Apify
const currentCompany = $input.first().json.companyName;

// Get all company names from the master list (input 2 from merge)
const masterListCompanies = $input.last().json;

// Check if current company exists in master list
// The master list is in the merged data from input 2
let companyExists = false;

// If masterListCompanies is an array, check if company exists
if (Array.isArray(masterListCompanies)) {
  companyExists = masterListCompanies.some(item => 
    item.companyName && item.companyName.toLowerCase() === currentCompany.toLowerCase()
  );
} else if (masterListCompanies && masterListCompanies.companyName) {
  // Single item comparison
  companyExists = masterListCompanies.companyName.toLowerCase() === currentCompany.toLowerCase();
}

// Only output if company does NOT exist in master list
if (!companyExists) {
  return $input.first().json; // Return the Apify result to continue
} else {
  return []; // Skip this company
}
